#include <bits/stdc++.h>
using namespace std;

class ThirdPartyLogger {
    string logLevel;
public:
    void writeLog(const string& level, const string& message) {
        logLevel = level;
        string upperLevel = level;
        transform(upperLevel.begin(), upperLevel.end(), upperLevel.begin(), ::toupper);
        cout << "[" << upperLevel << "] [ThirdParty] " << message << endl;
    }

    void sendAlert(const string& message, int severity) {
        cout << "[ALERT] Severity-" << severity << ": " << message << endl;
    }

    string getLastLogLevel() const {
        return logLevel;
    }
};

int main() {
    ThirdPartyLogger thirdParty;
    thirdParty.writeLog("info", "Application started");
    thirdParty.sendAlert("Disk usage critical", 3);
    cout << "Last log level: " << thirdParty.getLastLogLevel() << endl;
    return 0;
}

