// Target interface
interface PaymentProcessor {
    void processPayment(double amount, String currency);
}

// Native implementation
class CreditCardProcessor implements PaymentProcessor {
    @Override
    public void processPayment(double amount, String currency) {
        System.out.println("CreditCard: Processing " + currency + " " + amount);
    }
}

// External payment libraries (Adaptees)
class PayPalAPI {
    public void makePayment(double amount, String currency) {
        System.out.println("PayPal API: Making payment of " 
                           + currency + " " + amount);
    }
}

class StripeAPI {
    public void chargeCustomer(double amount, String currency) {
        System.out.println("Stripe API: Charging customer " 
                           + currency + " " + amount);
    }
}

// Adapters
class PayPalAdapter implements PaymentProcessor {
    private final PayPalAPI api;

    public PayPalAdapter(PayPalAPI api) {
        this.api = api;
    }

    @Override
    public void processPayment(double amount, String currency) {
        api.makePayment(amount, currency);
    }
}

class StripeAdapter implements PaymentProcessor {
    private final StripeAPI api;

    public StripeAdapter(StripeAPI api) {
        this.api = api;
    }

    @Override
    public void processPayment(double amount, String currency) {
        api.chargeCustomer(amount, currency);
    }
}

// Client
class CheckoutService {
    public void checkout(double amount, String currency, String method) {
        PaymentProcessor processor;

        switch (method.toLowerCase()) {
            case "creditcard":
                processor = new CreditCardProcessor();
                break;
            case "paypal":
                processor = new PayPalAdapter(new PayPalAPI());
                break;
            case "stripe":
                processor = new StripeAdapter(new StripeAPI());
                break;
            default:
                System.out.println("Unsupported payment method: " + method);
                return;
        }

        processor.processPayment(amount, currency);
    }
}

// Main
public class Main {
    public static void main(String[] args) {
        CheckoutService checkout = new CheckoutService();
        checkout.checkout(99.99,  "USD", "creditcard");
        checkout.checkout(149.99, "USD", "paypal");
        checkout.checkout(199.99, "USD", "stripe");
        checkout.checkout(49.99,  "USD", "bitcoin");
    }
}

