#include <bits/stdc++.h>
using namespace std;

// Target interface
class PaymentProcessor {
public:
    virtual void processPayment(double amount, const string& currency) = 0;
    virtual ~PaymentProcessor() = default;
};

// Native implementation
class CreditCardProcessor : public PaymentProcessor {
public:
    void processPayment(double amount, const string& currency) override {
        cout << "CreditCard: Processing " << currency << " " << amount << endl;
    }
};

// External payment libraries (Adaptees)
class PayPalAPI {
public:
    void makePayment(double amount, const string& currency) {
        cout << "PayPal API: Making payment of " << currency << " " << amount << endl;
    }
};

class StripeAPI {
public:
    void chargeCustomer(double amount, const string& currency) {
        cout << "Stripe API: Charging customer " << currency << " " << amount << endl;
    }
};

// Adapters
class PayPalAdapter : public PaymentProcessor {
    PayPalAPI api;
public:
    PayPalAdapter(PayPalAPI api) : api(api) {}

    void processPayment(double amount, const string& currency) override {
        api.makePayment(amount, currency);
    }
};

class StripeAdapter : public PaymentProcessor {
    StripeAPI api;
public:
    StripeAdapter(StripeAPI api) : api(api) {}

    void processPayment(double amount, const string& currency) override {
        api.chargeCustomer(amount, currency);
    }
};

// Client
class CheckoutService {
public:
    void checkout(double amount, const string& currency, string method) {
        transform(method.begin(), method.end(), method.begin(), ::tolower);

        unique_ptr<PaymentProcessor> processor;

        if (method == "creditcard") {
            processor = make_unique<CreditCardProcessor>();
        } else if (method == "paypal") {
            processor = make_unique<PayPalAdapter>(PayPalAPI());
        } else if (method == "stripe") {
            processor = make_unique<StripeAdapter>(StripeAPI());
        } else {
            cout << "Unsupported payment method: " << method << endl;
            return;
        }

        processor->processPayment(amount, currency);
    }
};

// Main
int main() {
    CheckoutService checkout;
    checkout.checkout(99.99, "USD", "creditcard");
    checkout.checkout(149.99, "USD", "paypal");
    checkout.checkout(199.99, "USD", "stripe");
    checkout.checkout(49.99, "USD", "bitcoin");
    return 0;
}
